test('RDF structure toggles independently of Turtle export and SVG includes the collection', async ({ page }) => {
    await openGraph(page);
    await expect(card(page)).toHaveClass(/\bcollection\b/);
    const compactTurtle = await download(page, 'Download Turtle');
    expect(compactTurtle.match(/rdf:first/g)).toHaveLength(3);
    expect(compactTurtle.match(/rdf:rest/g)).toHaveLength(3);
    const compactSvg = await download(page, 'Download SVG image');
    expect(compactSvg).toContain('3 items');
    expect(compactSvg).toContain('second');

    const details = await inspect(page, '<_:members-1>');
    await details.getByRole('button', { name: 'Show RDF structure', exact: true }).click();
    await expect(card(page)).not.toHaveClass(/\bcollection\b/);
    await expect(node(page, '<_:members-2>')).toBeAttached();
    await expect(node(page, '<_:members-3>')).toBeAttached();
    expect(await download(page, 'Download Turtle')).toBe(compactTurtle);
    await details.getByRole('button', { name: 'Show collection', exact: true }).click();
    await expect(card(page)).toHaveClass(/\bcollection\b/);
    await expect(node(page, '<_:members-2>')).toHaveCount(0);
});

